import{z as i,x as n,o as E,c as A,q as l,j as B,D as e,d as r,s,S as o}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"跨柜光模块把多柜收成一个逻辑节点","description":"","frontmatter":{"title":"跨柜光模块把多柜收成一个逻辑节点","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ub-optical-cabinets.md","filePath":"llm/ub-optical-cabinets.md","lastUpdated":1791063341000}'),p={name:"llm/ub-optical-cabinets.md"};function d(h,a,C,c,u,D){const t=n("Mermaid");return E(),A("div",null,[a[2]||(a[2]=l('<h1 id="跨柜光模块把多柜收成一个逻辑节点" tabindex="-1">跨柜光模块把多柜收成一个逻辑节点 <a class="header-anchor" href="#跨柜光模块把多柜收成一个逻辑节点" aria-label="Permalink to &quot;跨柜光模块把多柜收成一个逻辑节点&quot;">​</a></h1><div class="epigraph"><p>计算柜与通信柜不在同一背板里；把 L1 接到 L2 的跨柜介质是光模块，软件仍看见一个 UB 域，而不是十六个独立机柜。</p><footer>—— 对照 CloudMatrix384 十六柜形态与 UB-Mesh「电直连优先、距离不够则上光」的公开原则</footer></div><p><a href="/llm/cloudmatrix-384">CloudMatrix 384</a> 横跨 16 个机柜：12 个计算柜放 48 个节点，4 个通信柜放 <a href="/llm/ub-l1-l2-planes">L2 UB 交换</a>。柜与柜之间没有一块能插 384 颗 NPU 的巨型背板。短距铜缆够用的是节点内、至多柜内背板；柜间距、通信柜与计算柜之间的扇出，公开架构用<strong>光模块</strong>把 UB 链路延长。逻辑上，这些光链路仍是 UB 平面的一部分，HCCL 进程组可以把 384 颗 910C 当成一块 Scale-Up 域。本篇写「光」在超节点里的职责：收口距离，而不是另建一张以太网。不填写未公开的光模块只数、每瓦比特或眼图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Scale-Up 想要的是低跳数、高带宽、内存/消息语义不断档。Scale-Up 的物理敌人是距离：电直连有长度上限，机房里 16 柜并排后，L1 到 L2 的线会超过无源铜缆的舒适区。<a href="/llm/ub-mesh">UB-Mesh</a> 的原则是能用电就用电，减少光模块以降低成本和失效率；但原则不是「超节点禁止光」。一旦拓扑需要把多柜接到中心交换层，光是把 UB 动词送到对面柜子的介质，不是把语义降成 RoCE。</p><p><span class="marginnote">术语翻译：无源铜缆就是「纯一根铜线靠电信号直连」，便宜、可靠，但信号跑几米就衰减到不能用；光模块是「电转光、光再转电」的小盒子，把同一信号送到十几米外，代价是多了会坏、要清洁、要备件的器件。</span></p><p>若跨柜改走数据中心以太网，384 张卡立刻回到 Scale-Out：TP All-Reduce 穿叶子，节点间带宽与时延不再「接近节点内」，超节点名存实亡。若坚持全铜，布线长度、信号完整性和柜布局会把规模钉死在单柜。CloudMatrix 的选择是：柜内/板上优先电，<strong>跨柜 UB 用光</strong>，通信柜专门承担光模块密度与 L2 供电。</p><h3 id="光模块接的是-ub-不是-vpc" tabindex="-1">光模块接的是 UB，不是 VPC <a class="header-anchor" href="#光模块接的是-ub-不是-vpc" aria-label="Permalink to &quot;光模块接的是 UB，不是 VPC&quot;">​</a></h3><p>VPC 平面上的擎天网卡也可以是高速以太网光口，那是南北向与存储。本篇的光模块指 <strong>L1–L2 之间的 UB 上行</strong>。两者可能并存在同一机房，甚至同一柜的不同托盘，但软件平面不同。把光模块计数混进「这台机器有多少 400G 以太网口」，会把 Scale-Up 端口当成 Scale-Out 端口来规划拥塞。RDMA 平面的 400 Gbps 级链路同样可以是光，那是超节点之间；384 内部的逻辑节点靠 UB 光，不靠把 RDMA 在柜间再绕一圈。</p><p><span class="marginnote">SemiAnalysis 等第三方拆解讨论过光模块数量与功耗。那些不是华为论文里的规格表。本文只采用「十六柜 + 通信柜承载 L2 + 跨柜需要光」这一形态结论，不转述未写入 CloudMatrix384 / UB-Mesh 论文的模块清单。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>物理布局按「计算柜环绕或夹着通信柜」来理解：L2 集中，L1 分散，中间是光纤。每颗 L1 扇出 16 条到本子平面的 16 颗 L2，这些扇出在跨柜时就是光链路。七个子平面意味着七组平行的光纤束。运维上，光模块故障首先表现为某一平面、某一节点上行的误码或掉链路，MatrixLink 一类控制面负责切路径；业务侧应把超节点看成可降级的整域，而不是自动拆成 48 台独立服务器继续跑 64 路 TP。</p><p><span class="marginnote">直觉类比：通信柜像小区的快递集散中心——12 栋楼（计算柜）各自的包裹先汇到 4 个中心（L2 子平面在其中），分拣后再分发。楼与中心之间的「传送带」就是跨柜光纤；中心一停电，全小区收发都受影响，这就是通信柜维护窗口等于逻辑节点维护窗口的原因。</span></p><p>逻辑节点的编程不变：进程仍按 NPU 设备号组 HCCL，KV 池仍按 UB 地址/消息访问。介质从铜换成光，不应当要求框架换一套 API。需要换的是值班：光模块的备件、清洁、固件与计算 NPU 不在同一个 SKU 里；通信柜的维护窗口等于逻辑节点的维护窗口。</p>',14)),(E(),B(o,null,{default:e(()=>[s(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20C1%5B%22%E8%AE%A1%E7%AE%97%E6%9F%9C%22%5D%0A%20%20%20%20L1%5B%22%E8%8A%82%E7%82%B9%20L1%22%5D%0A%20%20end%0A%20%20subgraph%20OPT%5B%22%E8%B7%A8%E6%9F%9C%E5%85%89%E6%A8%A1%E5%9D%97%22%5D%0A%20%20%20%20M%5B%22UB%20%E4%B8%8A%E8%A1%8C%E5%85%89%E9%93%BE%E8%B7%AF%22%5D%0A%20%20end%0A%20%20subgraph%20C2%5B%22%E9%80%9A%E4%BF%A1%E6%9F%9C%22%5D%0A%20%20%20%20L2%5B%22L2%20%E5%AD%90%E5%B9%B3%E9%9D%A2%22%5D%0A%20%20end%0A%20%20L1%20--%3E%20M%20--%3E%20L2%0A%20%20L2%20--%3E%20M2%5B%22%E5%9B%9E%E7%A8%8B%E5%85%89%22%5D%20--%3E%20L1%0A%20%20L2%20-.-%3E%20%7C%22%E4%BB%8D%E6%98%AF%20UB%20%E5%8A%A8%E8%AF%8D%22%7C%20LOG%5B%22%E4%B8%80%E5%9D%97%E9%80%BB%E8%BE%91%E8%8A%82%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h3 id="与电直连如何分工" tabindex="-1">与电直连如何分工 <a class="header-anchor" href="#与电直连如何分工" aria-label="Permalink to &quot;与电直连如何分工&quot;">​</a></h3><p>节点内 8+4 到板载 L1：短距电。柜内若还有背板连接，优先电。出柜到通信柜：光。超节点之间：RoCE 光或电视机房而定，已是 Scale-Out。UB-Mesh 论文里短距无源电缆占线缆估计的大部分，正是因为大量互连被压在板、柜局部；384 要把 48 节点接到 4 个通信柜，剩下那截「非局部」必须光。读成本时不要只用 Clos 的「全光」去比，也不要假装 384 是全铜超节点。</p><p>液冷与供电在通信柜同样是柜级设施：光模块密集处的热设计属于交付工程。算法工程师可以不选模块型号，但不能在可用性模型里把通信柜当成「没有计算所以不重要的空柜」。</p><p><span class="marginnote">华为公开材料把超节点写成紧耦合逻辑节点，节点间性能接近节点内。光的插入损耗与转发跳数已被算进那张「接近」里。不要在光路上再叠加一次「按以太网 3 微秒 hop」的经验值去改 TP 度。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光模块做的是物理层：把 UB 的高速串行信号送到另一柜的 L2 端口。L2 转发的仍是 UB 包，Load/Store 与 Message 动词不在光纤上改写。因此「逻辑节点」成立于协议与编排，光纤只是让协议够得着。额外代价是：光电转换的失效模式（模块、链路、连接器）和铜不同，MTBF 模型应按光链路条数来做——这正是 UB-Mesh 想少用光的原因。384 在规模与少光之间取了折中：比全 Clos 少很多光，比单柜全铜多一截跨柜光。</p><p>跳数上，跨节点路径是 L1–L2–L1，相对盒内多两跳交换加一段光。论文用系统测量说明这段附加时延在微秒级、带宽衰减很小，见 <a href="/llm/ub-near-local-perf">近本地性能</a>。机制上，这就是「逻辑节点」可对 TP/EP 成立的定量依据：框架看到的是一块加速器，物理上是光连起来的 16 柜。</p><p><span class="marginnote">常见误区：看到「多两跳交换」就用以太网「每跳 3 微秒」的经验值去心算时延。UB 的 L1/L2 是同一超节点内的加速器互连跳，论文的系统测量把整段附加压在微秒以下到约 1 µs；拿普通数据中心网络的 hop 表来外推，会凭空多算出一个数量级。</span></p><h3 id="故障爆炸半径" tabindex="-1">故障爆炸半径 <a class="header-anchor" href="#故障爆炸半径" aria-label="Permalink to &quot;故障爆炸半径&quot;">​</a></h3><p>一批光模块或一柜 L2 掉线，逻辑节点的带宽或连通性降级。调度应摘域，而不是让剩余平面硬扛原 TP 度直到 NCCL/HCCL 超时。更换光模块的操作在通信柜，计算柜上的训练进程仍要按超节点作业来暂停。这与「只换一张计算刀片」的 HCCS 八卡机不同，见 <a href="/llm/hccs-to-ub">HCCS 到 UB</a>。</p>',10)),(E(),B(o,null,{default:e(()=>[s(t,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%85%89%E9%93%BE%E8%B7%AF%20%2F%20%E4%B8%80%E6%9F%9C%20L2%20%E6%95%85%E9%9A%9C%22%5D%20--%3E%20D%7B%22%E5%89%A9%E4%BD%99%E5%B9%B3%E9%9D%A2%E8%BF%98%E6%89%9B%E5%BE%97%E4%BD%8F%E5%90%97%3F%22%7D%0A%20%20D%20--%3E%7C%22%E5%B8%A6%E5%AE%BD%E4%BB%8D%E5%A4%9F%E5%8E%9F%E5%B9%B6%E8%A1%8C%E5%BA%A6%22%7C%20K%5B%22%E6%8E%A7%E5%88%B6%E9%9D%A2%E5%88%87%E8%B7%AF%E5%BE%84%20%C2%B7%20%E4%BD%9C%E4%B8%9A%E7%BB%A7%E7%BB%AD%E8%B7%91%22%5D%0A%20%20D%20--%3E%7C%22%E5%B8%A6%E5%AE%BD%E4%B8%8D%E8%B6%B3%E6%88%96%E8%BF%9E%E9%80%9A%E6%80%A7%E7%A0%B4%22%7C%20P%5B%22%E6%91%98%E5%9F%9F%EF%BC%9A%E6%8C%89%E8%B6%85%E8%8A%82%E7%82%B9%E4%BD%9C%E4%B8%9A%E6%9A%82%E5%81%9C%22%5D%0A%20%20P%20--%3E%20W%5B%22%E9%80%9A%E4%BF%A1%E6%9F%9C%E6%8D%A2%E6%A8%A1%E5%9D%97%20%C2%B7%20%E8%AE%A1%E7%AE%97%E6%9F%9C%E8%AE%AD%E7%BB%83%E5%90%8C%E6%AD%A5%E5%81%9C%22%5D%0A%20%20W%20--%3E%20R%5B%22%E6%81%A2%E5%A4%8D%E5%90%8E%E9%87%8D%E6%96%B0%E6%95%B4%E5%9F%9F%E6%8B%89%E8%B5%B7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把跨柜光模块写成「昇腾的 InfiniBand」。不要在未提供 UB 的普通机柜之间用以太网交换机「模拟通信柜」。不要公开未发布的模块速率表。距离再拉长（机房跨列、跨层）是否仍保证「接近节点内」，要以该部署的测量为准；论文的近本地数字绑的是其 384 超节点布局，不是任意光纤公里数。</p><p>与 NVL72 单柜铜缆交换的对照：华为用多柜 + 光换更大的 Scale-Up 域；NVIDIA 用单柜高密度换更短的电。两者都是 Scale-Up，介质策略不同，不能把光模块数量直接当成谁更先进的分数。</p><p><span class="marginnote">出处：CloudMatrix384 论文的 16 柜与通信柜角色；UB-Mesh 论文的电直连优先与光模块成本/可靠性讨论。模块级 BOM 不以第三方拆解为准。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>16 柜超节点靠跨柜光模块把计算柜的 L1 接到通信柜的 L2，软件仍是一块 UB 逻辑节点。</li><li>这些光链路属于 UB Scale-Up，与 VPC/RDMA 光口分平面记账。</li><li>电直连覆盖板/柜局部，光覆盖柜间距；原则是优先电，不是禁止光。</li><li>通信柜维护 = 逻辑节点维护；光故障按域降级，不要拆成 48 台独立机继续宽 TP。</li><li>附加时延与带宽衰减用论文的近本地指标理解，不套以太网 hop 经验。</li><li>出处：CloudMatrix384 与 UB-Mesh 公开论文。</li></ul>',6))])}const _=i(p,[["render",d]]);export{L as __pageData,_ as default};
